-- Seed catalog: ~49 real, publicly known courses/resources across 7 broad domains.
-- Descriptions are original summaries, not copied marketing copy. Run after
-- supabase/migrations/0001_init.sql has been applied.
-- skills_taught / prerequisite_skills are skill tags, not course IDs — the
-- recommendation engine chains courses by matching one course's skills_taught
-- against another's prerequisite_skills (see docs/adr/0003).

insert into courses (title, description, domain, level, duration_hours, skills_taught, prerequisite_skills, source_url) values

